{"command":"cat << 'EOF' > test_term.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
	"strconv"
)

func getTermSize() (int, int) {
	cmd := exec.Command("stty", "size")
	cmd.Stdin = os.Stdin
	out, err := cmd.Output()
	if err != nil {
		return 80, 24
	}
	parts := strings.Split(strings.TrimSpace(string(out)), " ")
	if len(parts) == 2 {
		h, _ := strconv.Atoi(parts[0])
		w, _ := strconv.Atoi(parts[1])
		return w, h
	}
	return 80, 24
}

func main() {
	w, h := getTermSize()
	fmt.Printf("%d %d\n", w, h)
}
EOF
go run test_term.go
"}

