{"command":"cat << 'EOF' > main.go
package main

import (
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strings"

	"golang.org/x/term"
	_ "golang.org/x/image/bmp"
	_ "golang.org/x/image/tiff"
	_ "golang.org/x/image/webp"
)

func getTermSize() (int, int) {
	w, h, err := term.GetSize(int(os.Stdout.Fd()))
	if err != nil || w == 0 || h == 0 {
		return 80, 24
	}
	return w, h
}

func main() {
	cfg := parseArgs()

	if cfg.help {
		fmt.Print(helpText)
		return
	}
	if cfg.version {
		fmt.Print(versionText)
		return
	}

	if len(cfg.positionals) == 0 {
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			fmt.Println("Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info")
			os.Exit(1)
		}
	}

	termW, termH := getTermSize()

	for _, path := range cfg.positionals {
		processImage(path, cfg, termW, termH)
	}
}

func BoxScale(img image.Image, targetWidth, targetHeight int) *image.RGBA {
	bounds := img.Bounds()
	srcW := bounds.Dx()
	srcH := bounds.Dy()
	out := image.NewRGBA(image.Rect(0, 0, targetWidth, targetHeight))
	if targetWidth == 0 || targetHeight == 0 {
		return out
	}
	for y := 0; y < targetHeight; y++ {
		for x := 0; x < targetWidth; x++ {
			startX := float64(x) * float64(srcW) / float64(targetWidth)
			endX := float64(x+1) * float64(srcW) / float64(targetWidth)
			startY := float64(y) * float64(srcH) / float64(targetHeight)
			endY := float64(y+1) * float64(srcH) / float64(targetHeight)

			var rSum, gSum, bSum, aSum float64
			var count float64

			minX, maxX := int(math.Floor(startX)), int(math.Ceil(endX))
			minY, maxY := int(math.Floor(startY)), int(math.Ceil(endY))

			for sy := minY; sy < maxY; sy++ {
				for sx := minX; sx < maxX; sx++ {
					if sx >= srcW || sy >= srcH {
						continue
					}
					ox1 := math.Max(startX, float64(sx))
					ox2 := math.Min(endX, float64(sx+1))
					oy1 := math.Max(startY, float64(sy))
					oy2 := math.Min(endY, float64(sy+1))

					if ox1 < ox2 && oy1 < oy2 {
						area := (ox2 - ox1) * (oy2 - oy1)
						r, g, b, a := img.At(bounds.Min.X+sx, bounds.Min.Y+sy).RGBA()
						rSum += float64(r>>8) * area
						gSum += float64(g>>8) * area
						bSum += float64(b>>8) * area
						aSum += float64(a>>8) * area
						count += area
					}
				}
			}
			if count > 0 {
				out.SetRGBA(x, y, color.RGBA{
					R: uint8(rSum / count),
					G: uint8(gSum / count),
					B: uint8(bSum / count),
					A: uint8(aSum / count),
				})
			}
		}
	}
	return out
}

func processImage(path string, cfg Config, termW, termH int) {
	file, err := os.Open(path)
	if err != nil {
		fmt.Printf("Error: unable to open file: open %s: no such file or directory\n", path)
		return
	}
	defer file.Close()

	img, _, err := image.Decode(file)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	bounds := img.Bounds()
	srcW := bounds.Dx()
	srcH := bounds.Dy()

	targetW, targetH := 0, 0
	if cfg.dimensions != "" {
		parts := strings.Split(cfg.dimensions, ",")
		if len(parts) == 2 {
			fmt.Sscanf(parts[0], "%d", &targetW)
			fmt.Sscanf(parts[1], "%d", &targetH)
		}
	} else if cfg.full {
		targetW = termW
		targetH = int(math.Round(float64(termW) * float64(srcH) / float64(srcW) * 0.5))
	} else if cfg.width > 0 && cfg.height > 0 {
		fmt.Println("Error: both --width and --height can't be set. Use --dimensions instead")
		os.Exit(1)
	} else if cfg.width > 0 {
		targetW = cfg.width
		targetH = int(math.Round(float64(targetW) * float64(srcH) / float64(srcW) * 0.5))
	} else if cfg.height > 0 {
		targetH = cfg.height
		targetW = int(math.Round(float64(targetH) * float64(srcW) / float64(srcH) * 2.0))
	} else {
		// default to terminal height, or somewhat constrained
		targetH = termH - 1 // reserve 1 line for prompt? original uses something similar
		if targetH <= 0 { targetH = 24 }
		targetW = int(math.Round(float64(targetH) * float64(srcW) / float64(srcH) * 2.0))
		if targetW > termW && termW > 0 {
			targetW = termW
			targetH = int(math.Round(float64(termW) * float64(srcH) / float64(srcW) * 0.5))
		}
	}

	if targetW <= 0 { targetW = 1 }
	if targetH <= 0 { targetH = 1 }

	if cfg.braille {
		scaled := BoxScale(img, targetW*2, targetH*4)
		if cfg.dither {
			scaled = ditherImage(scaled)
		}
		printBraille(scaled, targetW, targetH, cfg)
	} else {
		scaled := BoxScale(img, targetW, targetH)
		printAscii(scaled, targetW, targetH, cfg)
	}
}
EOF
"}

