package main

import (
	"fmt"
	"image"
	"image/color"
)

const simpleMap = " .:-=+*#%@"
const complexMap = " .'\\`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"

func getGray(c color.RGBA) int {
	return int(0.299*float64(c.R) + 0.587*float64(c.G) + 0.114*float64(c.B))
}

func printAscii(img *image.RGBA, w, h int, cfg Config) {
	charMap := simpleMap
	if cfg.complex {
		charMap = complexMap
	}
	if cfg.charMap != "" {
		charMap = cfg.charMap
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			sx := x
			sy := y
			if cfg.flipX { sx = w - 1 - x }
			if cfg.flipY { sy = h - 1 - y }
			c := img.RGBAAt(sx, sy)

			if cfg.negative {
				c.R = 255 - c.R
				c.G = 255 - c.G
				c.B = 255 - c.B
			}

			gray := getGray(c)
			idx := (gray * len(charMap)) / 255
			if idx >= len(charMap) {
				idx = len(charMap) - 1
			}
			ch := charMap[idx]

			if cfg.color && !cfg.grayscale {
				if cfg.colorBg {
					fmt.Printf("\033[48;2;%d;%d;%dm%c\033[0m", c.R, c.G, c.B, ch)
				} else {
					fmt.Printf("\033[38;2;%d;%d;%dm%c\033[0m", c.R, c.G, c.B, ch)
				}
			} else if cfg.grayscale {
				if cfg.colorBg {
					fmt.Printf("\033[48;2;%d;%d;%dm%c\033[0m", gray, gray, gray, ch)
				} else {
					fmt.Printf("\033[38;2;%d;%d;%dm%c\033[0m", gray, gray, gray, ch)
				}
			} else {
				fmt.Printf("%c", ch)
			}
		}
		fmt.Println()
	}
}

func printBraille(img *image.RGBA, w, h int, cfg Config) {
	threshold := cfg.threshold
	if cfg.dither {
		threshold = 128 // Negates --threshold flag
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			sx := x
			sy := y
			if cfg.flipX { sx = w - 1 - x }
			if cfg.flipY { sy = h - 1 - y }

			offset := 0
			// 2x4 block
			dots := []struct{ dx, dy, val int }{
				{0, 0, 1}, {0, 1, 2}, {0, 2, 4}, {1, 0, 8},
				{1, 1, 16}, {1, 2, 32}, {0, 3, 64}, {1, 3, 128},
			}

			var avgR, avgG, avgB int
			for _, d := range dots {
				c := img.RGBAAt(sx*2+d.dx, sy*4+d.dy)
				if cfg.negative {
					c.R = 255 - c.R
					c.G = 255 - c.G
					c.B = 255 - c.B
				}
				avgR += int(c.R)
				avgG += int(c.G)
				avgB += int(c.B)
				gray := getGray(c)
				if gray >= threshold {
					offset += d.val
				}
			}
			avgR /= 8
			avgG /= 8
			avgB /= 8

			brailleChar := rune(0x2800 + offset)
			gray := int(0.299*float64(avgR) + 0.587*float64(avgG) + 0.114*float64(avgB))

			if cfg.color && !cfg.grayscale {
				if cfg.colorBg {
					fmt.Printf("\033[48;2;%d;%d;%dm%c\033[0m", avgR, avgG, avgB, brailleChar)
				} else {
					fmt.Printf("\033[38;2;%d;%d;%dm%c\033[0m", avgR, avgG, avgB, brailleChar)
				}
			} else if cfg.grayscale {
				if cfg.colorBg {
					fmt.Printf("\033[48;2;%d;%d;%dm%c\033[0m", gray, gray, gray, brailleChar)
				} else {
					fmt.Printf("\033[38;2;%d;%d;%dm%c\033[0m", gray, gray, gray, brailleChar)
				}
			} else {
				fmt.Printf("%c", brailleChar)
			}
		}
		fmt.Println()
	}
}

func ditherImage(img *image.RGBA) *image.RGBA {
	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	grays := make([][]float64, h)
	for y := 0; y < h; y++ {
		grays[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			c := img.RGBAAt(x, y)
			grays[y][x] = 0.299*float64(c.R) + 0.587*float64(c.G) + 0.114*float64(c.B)
		}
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			old := grays[y][x]
			newVal := float64(0)
			if old >= 128 {
				newVal = 255
			}
			err := old - newVal

			if x+1 < w { grays[y][x+1] += err * 7 / 16.0 }
			if y+1 < h {
				if x-1 >= 0 { grays[y+1][x-1] += err * 3 / 16.0 }
				grays[y+1][x] += err * 5 / 16.0
				if x+1 < w { grays[y+1][x+1] += err * 1 / 16.0 }
			}
		}
	}

	out := image.NewRGBA(bounds)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			v := int(grays[y][x])
			if v < 0 { v = 0 }
			if v > 255 { v = 255 }
			out.SetRGBA(x, y, color.RGBA{uint8(v), uint8(v), uint8(v), 255})
		}
	}
	return out
}
