				} else {
					fmt.Printf("\033[38;2;%d;%d;%dm%c\033[0m", avgR, avgG, avgB, brailleChar)
				}
			} else if cfg.grayscale {
				if cfg.colorBg {
					fmt.Printf("\033[48;2;%d;%d;%dm%c\033[0m", gray, gray, gray, brailleChar)
				} else {
					fmt.Printf("\033[38;2;%d;%d;%dm%c\033[0m", gray, gray, gray, brailleChar)
				}
			} else {
				fmt.Printf("%c", brailleChar)
			}
		}
		fmt.Println()
	}
}

func ditherImage(img *image.RGBA) *image.RGBA {
	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	grays := make([][]float64, h)
	for y := 0; y < h; y++ {
		grays[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			c := img.RGBAAt(x, y)
			grays[y][x] = 0.299*float64(c.R) + 0.587*float64(c.G) + 0.114*float64(c.B)
		}
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			old := grays[y][x]
			newVal := float64(0)
			if old >= 128 {
				newVal = 255
			}
			err := old - newVal

			if x+1 < w { grays[y][x+1] += err * 7 / 16.0 }
			if y+1 < h {
				if x-1 >= 0 { grays[y+1][x-1] += err * 3 / 16.0 }
				grays[y+1][x] += err * 5 / 16.0
				if x+1 < w { grays[y+1][x+1] += err * 1 / 16.0 }
			}
		}
	}

	out := image.NewRGBA(bounds)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			v := int(grays[y][x])
			if v < 0 { v = 0 }
			if v > 255 { v = 255 }
			out.SetRGBA(x, y, color.RGBA{uint8(v), uint8(v), uint8(v), 255})
		}
	}
	return out
}
