func getTermSize() (int, int) {
	w, h, err := term.GetSize(int(os.Stdout.Fd()))
	if err != nil || w <= 0 || h <= 0 {
		return 80, 24
	}
	return w, h
}

func main() {
	cfg := parseArgs()

	if cfg.help {
		fmt.Print(helpText)
